static int _valid_utf8(const unsigned char * text, size_t length){
  size_t i = 0;
  while(i < length){
    unsigned char c = text[i ++];
    if(c < 0x80) continue;
    int extra = 0, minimum = 0;
    unsigned code = 0;
    if((c & 0xe0) == 0xc0){
      extra = 1;
      minimum = 0x80;
      code = c & 0x1f;
    }
    else if((c & 0xf0) == 0xe0){
      extra = 2;
      minimum = 0x800;
      code = c & 0x0f;
    }
    else if((c & 0xf8) == 0xf0){
      extra = 3;
      minimum = 0x10000;
      code = c & 0x07;
    }
    else return 0;
    if(i + extra > length) return 0;
    while(extra --){
      unsigned char next = text[i ++];
      if((next & 0xc0) != 0x80) return 0;
      code =(code << 6) |(next & 0x3f);
    }
    if(code < minimum ||(code >= 0xd800 && code <= 0xdfff) || code > 0x10ffff) return 0;
  }
  return 1;
}

